  -webkit-appearance:none !important; appearance:none !important;
  padding:0 4px !important; line-height:1.3 !important;
  color:var(--ry-input-ink) !important; -webkit-text-fill-color:var(--ry-input-ink) !important;
  caret-color:var(--ry-input-ink) !important;
}
#chat-detail-screen .input-box-custom::placeholder,
.chat-detail-screen .input-area-custom .input-box-custom::placeholder{
  color:transparent !important; -webkit-text-fill-color:transparent !important;
}

.chat-detail-screen .input-area-custom :is(.input-btn-mic, .input-btn-sticker){
  opacity:0 !important; pointer-events:auto !important; cursor:pointer !important;
  background:transparent !important; box-shadow:none !important; border:0 !important;
  -webkit-tap-highlight-color:transparent !important;
}

.chat-detail-screen .input-area-custom .input-btn-ai{
  position:relative !important; flex:0 0 28px !important;
  width:28px !important; height:28px !important; min-width:28px !important;
  padding:0 !important; margin:0 !important;
  border:0 !important; border-radius:0 !important;
  background:transparent !important; background-image:none !important;
  box-shadow:none !important; color:transparent !important; opacity:1 !important;
  transform:none !important; filter:none !important;
}
.chat-detail-screen .input-area-custom .input-btn-ai > *{ opacity:0 !important; }
.chat-detail-screen .input-area-custom .input-btn-ai::after{
  content:"" !important; position:absolute; inset:0; background-color:var(--ry-icon); pointer-events:none;
  -webkit-mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.6' stroke-linecap='round'><circle cx='12' cy='8' r='4'/><path d='M5 20c0-3.6 3.2-5.6 7-5.6s7 2 7 5.6'/></svg>") no-repeat center/21px 21px;
          mask:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='1.6' stroke-linecap='round'><circle cx='12' cy='8' r='4'/><path d='M5 20c0-3.6 3.2-5.6 7-5.6s7 2 7 5.6'/></svg>") no-repeat center/21px 21px;
}

/* ENTER:高度锁死 22px */
#chat-detail-screen .input-area-custom .send-btn-custom,
.chat-detail-screen .input-area-custom .send-btn-custom{
  position:relative !important; flex:0 0 auto !important; align-self:center !important;
  box-sizing:border-box !important;
  width:auto !important; min-width:52px !important;
  height:var(--ry-enter-h) !important; min-height:var(--ry-enter-h) !important; max-height:var(--ry-enter-h) !important;
  padding:0 8px !important; margin:0 !important; line-height:0 !important;
  border:1px solid var(--ry-enter-line) !important; border-radius:5px !important;
  background:var(--ry-page) !important; background-image:none !important;
  box-shadow:none !important; color:transparent !important; opacity:1 !important;
  transform:none !important; filter:none !important; aspect-ratio:auto !important;
}
.chat-detail-screen .input-area-custom .send-btn-custom > *{ opacity:0 !important; max-height:var(--ry-enter-h) !important; }
.chat-detail-screen .input-area-custom .send-btn-custom::after{
  content:"ENTER" !important; position:absolute; inset:0;
  display:flex; align-items:center; justify-content:center;
  font-size:11px; font-weight:600; color:var(--ry-enter-ink); letter-spacing:.04em; line-height:1;
  pointer-events:none;
}
.chat-detail-screen .input-area-custom .send-btn-custom:disabled{ opacity:.4 !important; }

